            if (type == MSG_PERIPHERAL) {

                buf.readUnsignedShort(); // data length

                int dataType = buf.readUnsignedByte();

                buf.readUnsignedByte(); // content length

                switch (dataType) {
                    case 0x01:
                        position.set(Position.KEY_FUEL_LEVEL,
